/**
 * Which Bukkit/Paper plugin a jar IS (plugin.yml / paper-plugin.yml `name` + `main`), read
 * without extracting anything. Used by the Minecraft installer to recognise a copy of the same
 * plugin that sits in plugins/ under ANOTHER file name (uploaded by hand, or left by an older
 * install): Paper loads only one plugin per name ("Ambiguous plugin name"), so placing ours
 * next to it would leave the customer with two copies and no way to tell which one runs.
 */
import { readZip } from "./archive";
import type { GuestFs } from "./guest-fs";
import type { PlacedFile, ResolvedPackage } from "./types";

export type PluginIdentity = { name: string; main: string | null; version: string | null };

const LIMITS = { maxEntries: 60_000, maxEntryBytes: 1024 * 1024, maxTotalBytes: 2 * 1024 * 1024, maxRatio: 1000 };
const yml = (text: string, key: string): string | null => {
  const m = new RegExp(`^${key}\\s*:\\s*(.+?)\\s*$`, "m").exec(text);
  if (!m) return null;
  const v = m[1].replace(/\s+#.*$/, "").replace(/^(['"])(.*)\1$/, "$2").trim();
  return v.length ? v.slice(0, 200) : null;
};

/** plugin.yml (or paper-plugin.yml) identity of a jar; null when it has none or is unreadable. */
export function pluginIdentity(jar: Buffer): PluginIdentity | null {
  try {
    const want = (n: string) => n === "plugin.yml" || n === "paper-plugin.yml";
    const entries = readZip(jar, LIMITS, { strictPaths: false, only: want });
