/** Build the Universe. Never throws: a project whose source fails is simply absent ("unknown"). */
export async function loadUniverse(ctx: LoadCtx): Promise<{ universe: Universe; errors: string[] }> {
  const universe: Universe = {};
  const errors: string[] = [];
  const max = ctx.maxProjects ?? 60;
  const inst = new Map(ctx.installed.map((p) => [p.key, p]));
  const v2p = new Map<string, string>();
  const queue: string[] = ctx.installed.filter((p) => !p.disabled).map((p) => p.key);
  const seen = new Set<string>();
  const rootMod = new Map<string, CatalogFacts>();
  for (const p of ctx.installed) if (p.root && p.modId && ctx.mods.get(p.modId)) rootMod.set(p.key, ctx.mods.get(p.modId)!);

  // Catalogue rows (fallback + mirror tags), one query.
  let catalog: CatalogVersionRow[] = [];
  if (ctx.catalog) {
    const ids = [...rootMod.values()].map((m) => m.id);
    catalog = ids.length ? await ctx.catalog(ids).catch(() => []) : [];
  }

  while (queue.length && seen.size < max) {
    const key = queue.shift()!;
    if (seen.has(key)) continue;
    seen.add(key);
    let info: ProjectInfo | null = null;
    try {
      if (key.startsWith("modrinth:")) info = await loadModrinth(key, ctx, inst.get(key), v2p);
      else if (key.startsWith("hangar:")) info = await loadHangar(key, ctx);
      else if (key.startsWith("thunderstore:")) info = await loadThunderstore(key, ctx, inst.get(key));
      else if (rootMod.has(key)) {
        for (const pi of await loadViaInstaller(rootMod.get(key)!, ctx)) {
          if (!universe[pi.key]) universe[pi.key] = pi;
          seen.add(pi.key);
        }
        continue;
      }
    } catch (e) {
      errors.push(`${key}: ${(e as Error).message}`.slice(0, 200));
    }
    // Upstream failed (or returned nothing) → the NX Labs catalogue, if it has this mod.
    const mod = rootMod.get(key);
    if ((!info || !info.versions.length) && mod) {
    return { key: pk.key, name: sm?.mod.name ?? pk.name, version: pk.version, versionId: pk.versionId, root: !!sm, modId, pinned: sm?.pinned ?? false, disabled: pk.disabled || sm?.status === "DISABLED", requires: pk.requires };
