/** Why this creator may not make this mod PUBLIC right now, or null. */
export async function publishBlockedReason(userId: string, rootBuildId: string, env: Record<string, string | undefined> = process.env): Promise<string | null> {
  if (await cyrusSuspension(userId, "community")) return PUBLISH_SUSPENDED;
