// Networking consent for EVERY path that puts a Cyrus version on a server (2026-10-15). Before this only the install
// route (/api/mod-builder/builds/[id]/install) and the delivery API checked lib/cyrus/capabilities.ts capabilityGate;
// the Install dialog (installCyrusMod), NxLabs installs, the Mods tab version switch, "Update all" and the Cyrus
// auto-update skipped it, so a version that connects to the internet could land without the owner reviewing its hosts,
// and even while the global switch `cyrus_mod_networking_enabled` was off.
// Rule: a version without a capabilities manifest passes. One with a manifest needs the switch on AND consent for that
// exact manifest: either sent with this request (acceptCapabilities = its sha256) or already given, meaning the version
// installed on this server now carries the identical manifest (same sha256). Server-only.
import type { ModBuild } from "@prisma/client";
import { db } from "../db";
import { cyrusDb } from "../cyrus/db";
import { getSettingBool } from "../settings";
import { capabilityGate, validateCapabilities } from "../cyrus/capabilities";
import { CYRUS_SOURCE } from "../cyrus/source";

export type CapabilityCheck = { ok: true } | { ok: false; status: number; code: string; error: string };

const capsOf = (b: Pick<ModBuild, "result"> | null) => ((b?.result as { capabilities?: unknown } | null)?.capabilities ?? null);

/** sha256 of the manifest the version installed on `serverId` carries (consent already given for it), or null. */
async function installedManifestSha(build: Pick<ModBuild, "id" | "rootBuildId">, serverId: string): Promise<string | null> {
  const gm = await db.gameMod.findFirst({ where: { source: CYRUS_SOURCE, sourceId: build.rootBuildId ?? build.id }, select: { id: true } });
  if (!gm) return null;
  const sm = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } }, select: { status: true, versionId: true } });
  if (!sm?.versionId || !["INSTALLED", "DISABLED", "UPDATING"].includes(sm.status)) return null;
  const cur = await cyrusDb.modBuild.findUnique({ where: { id: sm.versionId }, select: { result: true } });
  const caps = capsOf(cur);
  if (caps == null) return null;
  const v = validateCapabilities(caps);
  return v.ok ? v.manifest.sha256 : null;
}

export async function capabilityCheck(build: Pick<ModBuild, "id" | "rootBuildId" | "result">, serverId: string, acceptCapabilities?: string | null): Promise<CapabilityCheck> {
  const caps = capsOf(build);
  if (caps == null) return { ok: true };
  const networkingEnabled = await getSettingBool("cyrus_mod_networking_enabled");
  const accepted = acceptCapabilities || (await installedManifestSha(build, serverId).catch(() => null));
  const g = capabilityGate({ capabilities: caps, networkingEnabled, acceptedSha256: accepted });
  return g.ok ? { ok: true } : { ok: false, status: g.status, code: g.code, error: g.error };
}
