// A server was deleted (worker DELETE job): drop the Cyrus records that only meant something while it existed. The
// platform's own install rows (ServerMod, ModUpdateRun, ...) cascade with the Server row; Cyrus tables have no foreign
// keys (separation by design), so before 2026-10-15 these stayed behind for every deleted server: managed-plugin
// reference rows (BetterModel / Pack Loader ref counts for a disk that no longer exists), open Broken / crash signals,
// and the builder's "last installed on <server>" pointer. The `server.deleted` platform event did the first part, but
// it is only emitted for servers with a Connect grant (CYRUS_SERVER_GRANTS + CYRUS_PLATFORM_EVENTS).
// Deliberately NOT done here: the free-token clawback for servers deleted soon after purchase (reverseServerGrants
// "deleted"): that changes balances and stays an owner decision (see the integration report). Idempotent; HOST SEAM:
// Cyrus tables only.
import { Prisma } from "@prisma/client";
import { cyrusDb as db } from "../db";

export async function cyrusServerGone(serverId: string, now = new Date()): Promise<{ managed: number; signals: number; lastInstall: number }> {
  if (!serverId) return { managed: 0, signals: 0, lastInstall: 0 };
  const managed = (await db.cyrusServerManagedPlugin.deleteMany({ where: { serverId } })).count;
  const signals = (await db.cyrusModSignal.updateMany({ where: { serverId, clearedAt: null }, data: { clearedAt: now } })).count;
  const lastInstall = (await db.modBuild.updateMany({ where: { lastInstall: { path: ["serverId"], equals: serverId } }, data: { lastInstall: Prisma.DbNull } })).count;
  return { managed, signals, lastInstall };
}
