// Cyrus <-> Nxeon integration (2026-10-15): "already on the server" recognition and update semantics through the REAL
// mods engine (lib/mods/engine.ts + the Minecraft installer) on a fake guest directory (LocalGuestFs). No DB, no SSH:
// only the jar source (the DB edge) is injected. The DB-backed flows are in test/cyrus-nxeon-integration-db.test.ts.
import "./_cyrus-server-only-shim";
import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtempSync, rmSync, existsSync, readFileSync, readdirSync, writeFileSync, mkdirSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { installOrUpdate, uninstall, loadState } from "../lib/mods/engine.ts";
import { LocalGuestFs, seedSandboxGuest } from "../lib/mods/guest-fs.ts";
import { minecraftInstaller } from "../lib/mods/installers/minecraft.ts";
import { setCyrusJarSource, CYRUS_SOURCE, type CyrusJar } from "../lib/mods/installers/cyrus.ts";
import { pluginIdentity } from "../lib/mods/plugin-identity.ts";
import { writeZip } from "../lib/mod-autoupdate/zip.ts";
import type { CatalogFacts, FamilyInstaller, ServerFacts } from "../lib/mods/types.ts";

const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");
function jar(name: string, version: string, main = `com.nxeon.${name}`): Buffer {
  return writeZip([
    { name: "plugin.yml", data: Buffer.from(`name: ${name}\nversion: '${version}'\nmain: ${main}\napi-version: '1.21'\ncommands:\n  ${name.toLowerCase()}:\n    description: x\n`) },
    { name: `${main.replace(/\./g, "/")}.class`, data: Buffer.from(`class-${version}`) },
  ]);
}
const server: ServerFacts = { id: "s1", family: "minecraft", variant: "paper", pinnedVersion: "1.21.11", config: null };
const mod: CatalogFacts = { id: "gm-coin", gameFamily: "minecraft", slug: "cyrus-root1", name: "CoinShop", source: CYRUS_SOURCE, sourceId: "root1", url: null, category: "Plugins", appliesToVariant: null, loaders: ["paper", "purpur"], gameVersions: ["1.21.11"], serverSide: "required" };
const noNet = async (): Promise<never> => { throw new Error("Cyrus installs never download"); };

type Ctx = { dir: string; fs: LocalGuestFs; plugins: string; deps: { fs: LocalGuestFs; fetcher: typeof noNet } };
async function guest(): Promise<Ctx> {
  const dir = mkdtempSync(path.join(tmpdir(), "cyrus-integ-"));
  const fs = new LocalGuestFs(dir);
  await seedSandboxGuest(fs, "minecraft", "paper");
  return { dir, fs, plugins: path.join(dir, "opt/mc/plugins"), deps: { fs, fetcher: noNet } };
}
function source(versions: Record<string, Buffer>) {
  setCyrusJarSource(async ({ targetBuildId }) => {
    const id = targetBuildId ?? Object.keys(versions).at(-1)!;
    const bytes = versions[id];
    if (!bytes) return { error: "That version isn't a finished build of this mod." };
    const v = pluginIdentity(bytes)!.version!;
    const out: CyrusJar = { build: { id, version: v, pluginName: "CoinShop", jarName: `CoinShop-${v}.jar`, jarSha256: sha(bytes), mcVersion: "1.21.11" }, name: "CoinShop", packageVersion: v, bytes };
    return out;
  });
}

test("plugin identity: name/main/version from plugin.yml (quoted, comments), null for a jar without one", () => {
  const id = pluginIdentity(jar("CoinShop", "1.2.0"))!;
  assert.deepEqual(id, { name: "CoinShop", main: "com.nxeon.CoinShop", version: "1.2.0" });
  const commented = writeZip([{ name: "plugin.yml", data: Buffer.from(`name: "Fancy Name" # the display\nmain: a.B\n`) }]);
  assert.equal(pluginIdentity(commented)?.name, "Fancy Name");
  assert.equal(pluginIdentity(writeZip([{ name: "x.txt", data: Buffer.from("x") }])), null);
  assert.equal(pluginIdentity(Buffer.from("not a zip")), null);
});

test("install twice: second run changes nothing; the state file has ONE package for the mod", async () => {
  const c = await guest();
  try {
    source({ b1: jar("CoinShop", "1.0.0") });
    const r1 = await installOrUpdate(minecraftInstaller, mod, server, c.deps);
    assert.ok(r1.ok, JSON.stringify(r1));
    const r2 = await installOrUpdate(minecraftInstaller, mod, server, c.deps);
    assert.ok(r2.ok && r2.changed.length === 0 && r2.restartRequired === false, JSON.stringify(r2));
    assert.match((r2 as { notes: string[] }).notes.join(" "), /already installed and up to date/);
    assert.deepEqual(readdirSync(c.plugins), ["CoinShop-1.0.0.jar"]);
    const st = await loadState(c.fs, "minecraft");
    assert.equal(Object.keys(st.packages).length, 1);
