function jarBytes(version: string, main = "com.nxeon.CoinShop", name = "CoinShop") {
  return writeZip([
    { name: "plugin.yml", data: Buffer.from(`name: ${name}\nversion: '${version}'\nmain: ${main}\napi-version: '1.21'\ncommands:\n  coinshop:\n    description: open the shop\n`) },
