    assert.equal(sm?.versionId, ROOT);
    assert.equal(sm?.version, "1.0.0");
    assert.equal(sm?.fileName, "CoinShop-1.0.0.jar");
    assert.deepEqual(plugins(ids.sa), ["CoinShop-1.0.0.jar"]);
    const gms = await db.gameMod.findMany({ where: { source: "cyrus", sourceId: ROOT } });
    assert.equal(gms.length, 1);
    assert.equal(gms[0].active, false, "never listed in the public catalogue");
    assert.equal(gms[0].authorName, "Ada Creator", "author tag from the creator's account");
    const page = await db.cyrusModPage.findUnique({ where: { rootBuildId: ROOT } });
    assert.equal(page?.visibility, "PRIVATE", "pages start private");
    assert.equal(page?.latestBuildId, ROOT);
    assert.equal(gms[0].url, `/dashboard/nxlabs/cyrus/${page!.slug}`);
    const audit = await db.auditLog.count({ where: { userId: ids.a, action: "gameserver.mod.install", detail: { contains: ids.sa } } });
    assert.equal(audit, 1);
  });

  it("install twice: no second job, no second row, plan says 'already installed'", async () => {
    const jobsBefore = await db.job.count({ where: { serverId: ids.sa } });
    const r = await I.installBuildToServer(await build(ROOT), ids.a, ids.sa, { waitMs: 0 });
    assert.ok(r.ok && r.queued === false && r.jobId === "", JSON.stringify(r));
    assert.equal(await db.job.count({ where: { serverId: ids.sa } }), jobsBefore);
    assert.equal(await db.serverMod.count({ where: { serverId: ids.sa, modId: ids.mod } }), 1);
    const plan = (await S.installPlansFor(await build(ROOT), ids.a)).plans.find((p) => p.server.id === ids.sa)!;
    assert.equal(plan.plan.op, "none");
  });

  it("a newer build = update available (Mods tab + lifecycle); a FAILED build never counts", async () => {
    await mkBuild(`${uniq}v2`, "1.1.0");
    await mkBuild(`${uniq}vf`, "1.2.0", { status: "failed" });
    const lc = (await S.lifecycleForServer(ids.sa))[0];
    assert.equal(lc.updateAvailable, true);
    assert.equal(lc.latestBuildId, `${uniq}v2`, "the failed build is not 'latest'");
    const sm = (await db.serverMod.findMany({ where: { serverId: ids.sa }, include: { mod: true } }));
    const info = (await INF.cyrusInfoForRows(sm, ids.a)).get(ids.mod)!;
    assert.equal(info.updateAvailable, true);
    assert.equal(info.latestPackageVersion, "1.1.0");
    const plan = (await S.installPlansFor(await build(`${uniq}v2`), ids.a)).plans.find((p) => p.server.id === ids.sa)!;
    assert.equal(plan.plan.op, "update");
  });

  it("double click on Update: two concurrent requests queue exactly ONE job (per-server lock); the update replaces the old jar, config kept", async () => {
    mkdirSync(path.join(guestDir, ids.sa, "opt/mc/plugins/CoinShop"), { recursive: true });
    writeFileSync(path.join(guestDir, ids.sa, "opt/mc/plugins/CoinShop/config.yml"), "price: 7 # owner\n");
    const b2 = await build(`${uniq}v2`);
    const [x, y] = await Promise.all([I.installBuildToServer(b2, ids.a, ids.sa, { waitMs: 0 }), I.installBuildToServer(b2, ids.a, ids.sa, { waitMs: 0 })]);
    const oks = [x, y].filter((r) => r.ok && r.queued);
    assert.equal(oks.length, 1, JSON.stringify([x, y]));
    const loser = [x, y].find((r) => !r.ok) as { error: string };
    assert.match(loser.error, /already running|busy/);
    assert.equal(await db.job.count({ where: { serverId: ids.sa, status: "QUEUED" } }), 1);
    const run = await runJobs(ids.sa);
    assert.deepEqual(run.errors, []);
    const sm = await row(ids.sa);
    assert.equal(sm?.versionId, `${uniq}v2`, sm?.error ?? "");
    assert.equal(sm?.version, "1.1.0");
    assert.deepEqual(plugins(ids.sa), ["CoinShop-1.1.0.jar"], "old jar removed: one copy loaded");
    assert.equal(readFileSync(path.join(guestDir, ids.sa, "opt/mc/plugins/CoinShop/config.yml"), "utf8"), "price: 7 # owner\n");
    assert.equal((await S.lifecycleForServer(ids.sa))[0].updateAvailable, false);
  });

  it("multi-server: the same mod on a second server is a second ServerMod of the SAME GameMod; a hand-uploaded copy there is recognised and replaced", async () => {
    mkdirSync(path.join(guestDir, ids.sa2, "opt/mc/plugins"), { recursive: true });
    writeFileSync(path.join(guestDir, ids.sa2, "opt/mc/plugins/coinshop-from-cyrus-download.jar"), jarBytes("1.0.0"));
    const r = await I.installBuildToServer(await build(`${uniq}v2`), ids.a, ids.sa2, { waitMs: 0 });
    assert.ok(r.ok, JSON.stringify(r));
    await runJobs(ids.sa2);
    const sm = await row(ids.sa2);
    assert.equal(sm?.status, "INSTALLED", sm?.error ?? "");
    assert.deepEqual(plugins(ids.sa2), ["CoinShop-1.1.0.jar"], "the hand copy is gone (backed up)");
    const job = await db.job.findFirst({ where: { serverId: ids.sa2, type: "GAME_MOD_SYNC" }, orderBy: { createdAt: "desc" } });
    assert.ok(((job?.payload as { result?: { changed?: string[] } }).result?.changed ?? []).some((c) => /added by hand/.test(c)));
    assert.equal(await db.gameMod.count({ where: { source: "cyrus", sourceId: ROOT } }), 1);
  });

  it("another plugin with the same plugin.yml name on the server: the install FAILS with a clear message and the row says so", async () => {
    await mkBuild(`${uniq}o1`, "2.0.0", { root: `${uniq}o1`, name: "Lobby", main: "com.nxeon.Lobby" });
    const s = ids.sa2;
    writeFileSync(path.join(guestDir, s, "opt/mc/plugins/LobbyPro.jar"), jarBytes("9.0", "net.vendor.lobby.Main", "Lobby"));
    const r = await I.installBuildToServer(await build(`${uniq}o1`), ids.a, s, { waitMs: 0 });
    assert.ok(r.ok);
    await runJobs(s);
    const sm = await db.serverMod.findUnique({ where: { serverId_modId: { serverId: s, modId: (r as { modId: string }).modId } } });
    assert.equal(sm?.status, "FAILED");
    assert.match(sm?.error ?? "", /LobbyPro\.jar is a different plugin that also calls itself Lobby/);
    assert.ok(plugins(s).includes("LobbyPro.jar") && !plugins(s).includes("Lobby-2.0.0.jar"), "nothing changed");
    const lc = (await S.lifecycleForServer(s)).find((x) => x.modId === sm!.modId)!;
    assert.equal(lc.view.state, "failed");
    // Uninstall a FAILED row: clears it without touching the other plugin.
    assert.ok((await Q.enqueueModOp(s, sm!.modId, "remove", { userId: ids.a, slug: "x" })).ok);
    await runJobs(s);
    assert.equal(await db.serverMod.count({ where: { serverId: s, modId: sm!.modId } }), 0);
    assert.ok(plugins(s).includes("LobbyPro.jar"));
  });

  it("delivery API after a Mods-engine install: the next version goes through the orchestrator (no false 'two jars' refusal)", async () => {
    await db.cyrusProject.create({ data: { id: `cp${uniq}a`, userId: ids.a, game: "minecraft", namespace: `nx_${uniq.slice(-8).padStart(8, "0")}`, rootBuildId: ROOT } as never });
    const b3 = await mkBuild(`${uniq}v3`, "1.3.0");
    const r = await DL.enqueueCyrusDelivery({ userId: ids.a, serverId: ids.sa, keyKind: "client", build: b3 as never, payload: { v: 1, op: "deliver", buildId: b3.id, restartPolicy: "next_restart", requestedBy: ids.a } });
    assert.ok(r.ok, JSON.stringify(r));
    assert.equal((await row(ids.sa))?.status, "UPDATING");
    const run = await runJobs(ids.sa);
    const job = await db.job.findUniqueOrThrow({ where: { id: (r as { jobId: string }).jobId } });
    const res = (job.payload as { result?: { cyrusDelivery?: { outcome?: string; error?: string } } }).result?.cyrusDelivery;
    assert.deepEqual(run.errors, [], JSON.stringify(res));
    assert.equal(res?.outcome, "pending_restart", JSON.stringify(res));
    const sm = await row(ids.sa);
    assert.equal(sm?.status, "INSTALLED");
    assert.equal(sm?.versionId, b3.id);
    assert.equal(sm?.version, "1.3.0", "delivery records the version string like the engine path");
    assert.deepEqual(plugins(ids.sa), ["CoinShop-1.3.0.jar"]);
  });

  it("an update whose health check fails is ROLLED BACK: the row goes back to the previous version with the reason", async () => {
    const { nxeonDeliveryJobDeps } = await import("../worker/cyrus-delivery.ts");
    const { runDeliveryJob } = await import("../lib/cyrus/delivery/job.ts");
    const { FakeServer, seedServer } = await import("./_cyrus-delivery-fakehost.ts");
    const b4 = await mkBuild(`${uniq}v4`, "1.4.0");
    const q = await DL.enqueueCyrusDelivery({ userId: ids.a, serverId: ids.sa, keyKind: "client", build: b4 as never, payload: { v: 1, op: "deliver", buildId: b4.id, restartPolicy: "now", requestedBy: ids.a } });
    assert.ok(q.ok, JSON.stringify(q));
    const fake = new FakeServer(); seedServer(fake);
    try {
      const deps = { ...nxeonDeliveryJobDeps({ ...process.env, CYRUS_DELIVERY: "1" }), host: () => fake.host({ failStep: "health" }) };
      const job = await db.job.findUniqueOrThrow({ where: { id: (q as { jobId: string }).jobId } });
      await assert.rejects(runDeliveryJob(job, deps as never), /rolled_back/);
      await db.job.update({ where: { id: job.id }, data: { status: "FAILED" } });
    } finally { fake.cleanup(); }
    const sm = await row(ids.sa);
    assert.equal(sm?.status, "INSTALLED");
    assert.equal(sm?.versionId, `${uniq}v3`, "previous version kept");
    assert.match(sm?.error ?? "", /^Rolled back: /);
    const lc = (await S.lifecycleForServer(ids.sa))[0];
    assert.ok(lc.view.notes.some((x) => /The update failed and the previous version was kept/.test(x)), JSON.stringify(lc.view));
  });

  it("uninstall: jar + state entry gone, ServerMod row deleted, the plugin's data folder kept", async () => {
    assert.ok((await Q.enqueueModOp(ids.sa2, ids.mod, "remove", { userId: ids.a, slug: "x" })).ok);
    await runJobs(ids.sa2);
    assert.equal(await row(ids.sa2), null);
    assert.ok(!plugins(ids.sa2).some((f) => f.startsWith("CoinShop")));
    const st = JSON.parse(readFileSync(path.join(guestDir, ids.sa2, "root/.nxeon-mods/state.json"), "utf8"));
    assert.equal(st.roots[ids.mod], undefined);
    assert.ok(!Object.keys(st.packages).some((k) => k === `cyrus:${ROOT}`));
  });

  it("eligibility gates: another user's server, a stopped server and a Fabric server are refused with clear reasons", async () => {
    const b = await build(ROOT);
    let r = await I.installEligibility(b, ids.a, ids.sb);
    assert.ok(!r.ok && r.error === "Server not found.");
    const stopped = await mkServer(ids.a, "stopped", { status: "STOPPED" });
    const fabric = await mkServer(ids.a, "fabric", { variant: "fabric" });
    ids.sx = stopped;
    r = await I.installEligibility(b, ids.a, stopped);
    assert.ok(!r.ok && /stopped/.test(r.error), JSON.stringify(r));
    r = await I.installEligibility(b, ids.a, fabric);
    assert.ok(!r.ok && /plugins need Paper or Purpur/.test(r.error), JSON.stringify(r));
    await db.server.delete({ where: { id: fabric } });
    // someone else's private build
    r = await I.installEligibility(b, ids.b, ids.sb, { allowPublic: true });
    assert.ok(!r.ok && r.error === "Not found.");
  });

  it("networking mods: refused on every path while the switch is off; with it on, consent is needed unless the SAME manifest is installed", async () => {
    const { capabilityCheck } = await import("../lib/modbuilder/capability-check.ts");
    const { validateCapabilities } = await import("../lib/cyrus/capabilities.ts");
    const net = await mkBuild(`${uniq}n1`, "1.5.0", { result: { capabilities: CAPS } });
    let r = await I.installBuildToServer(net, ids.a, ids.sa, { waitMs: 0 });
    assert.ok(!r.ok && /switched off/.test(r.error), JSON.stringify(r));
    await setSetting("cyrus_mod_networking_enabled", "true");
    r = await I.installBuildToServer(net, ids.a, ids.sa, { waitMs: 0 });
    assert.ok(!r.ok && /Review what this mod connects to/.test(r.error), JSON.stringify(r));
    const shaOk = (validateCapabilities(CAPS) as { manifest: { sha256: string } }).manifest.sha256;
    r = await I.installBuildToServer(net, ids.a, ids.sa, { waitMs: 0, acceptCapabilities: shaOk });
    assert.ok(r.ok, JSON.stringify(r));
    await runJobs(ids.sa);
    assert.equal((await row(ids.sa))?.versionId, net.id);
    // a later version with the SAME manifest: consent stands (switch version / update all / auto-update can apply it)
    const same = await mkBuild(`${uniq}n2`, "1.6.0", { result: { capabilities: CAPS } });
    assert.deepEqual(await capabilityCheck(same, ids.sa), { ok: true });
    // a version that adds a host: needs a new review
    const more = await mkBuild(`${uniq}n3`, "1.7.0", { result: { capabilities: { ...CAPS, network: { ...CAPS.network, hosts: [...CAPS.network.hosts, { host: "evil.example.org", purpose: "x" }] } } } });
    const c = await capabilityCheck(more, ids.sa);
    assert.ok(!c.ok && c.code === "consent_required");
    await setSetting("cyrus_mod_networking_enabled", "false");
    assert.ok(!(await capabilityCheck(same, ids.sa)).ok, "the global switch wins over earlier consent");
    // back to a plain version for the next cases
    await db.modBuild.updateMany({ where: { id: { in: [same.id, more.id] } }, data: { status: "failed" } });
    assert.ok((await Q.enqueueModOp(ids.sa, ids.mod, "update", { userId: ids.a, slug: "x" }, { targetVersionId: `${uniq}v3` })).ok);
    await runJobs(ids.sa);
    assert.equal((await row(ids.sa))?.versionId, `${uniq}v3`);
    await db.modBuild.update({ where: { id: net.id }, data: { status: "failed" } });
  });

  it("published on NxLabs: another player installs it; unpublish leaves their copy running but stops offering updates", async () => {
    await setSetting("cyrus_install_published_enabled", "true");
    await setSetting("cyrus_mods_public_enabled", "true");
    await db.cyrusModPage.update({ where: { rootBuildId: ROOT }, data: { visibility: "PUBLIC", publishedAt: new Date() } });
    const head = await build(`${uniq}v3`);
    const r = await I.installBuildToServer(head, ids.b, ids.sb, { waitMs: 0, allowPublic: true });
    assert.ok(r.ok, JSON.stringify(r));
    await runJobs(ids.sb);
    assert.equal((await row(ids.sb))?.status, "INSTALLED", (await row(ids.sb))?.error ?? "");
    // the creator ships v5 while public: an update for the player
    await mkBuild(`${uniq}v5`, "1.8.0");
    assert.equal((await S.lifecycleForServer(ids.sb))[0].updateAvailable, true);
    // unpublish: installed copy unaffected, no update offered, a forced update is refused by the worker
    await db.cyrusModPage.update({ where: { rootBuildId: ROOT }, data: { visibility: "PRIVATE" } });
    const lc = (await S.lifecycleForServer(ids.sb))[0];
    assert.equal(lc.updateAvailable, false, "not an update this server can take");
    assert.notEqual(lc.view.state, "outdated");
    const rows = await db.serverMod.findMany({ where: { serverId: ids.sb }, include: { mod: true } });
    assert.equal((await INF.cyrusInfoForRows(rows, ids.b)).get(ids.mod)?.updateAvailable, false);
    assert.equal((await INF.cyrusInfoForRows(rows, ids.a)).get(ids.mod)?.updateAvailable, true, "the creator's own view is unchanged");
    assert.deepEqual(plugins(ids.sb), ["CoinShop-1.3.0.jar"]);
    assert.ok((await Q.enqueueModOp(ids.sb, ids.mod, "update", { userId: ids.b, slug: "x" }, { targetVersionId: `${uniq}v5` })).ok);
    await runJobs(ids.sb);
    const sm = await row(ids.sb);
    assert.equal(sm?.status, "INSTALLED");
    assert.equal(sm?.versionId, `${uniq}v3`);
    assert.match(sm?.error ?? "", /isn't published/);
    assert.deepEqual(plugins(ids.sb), ["CoinShop-1.3.0.jar"], "still running the copy they had");
    // takedown (hiddenAt) behaves the same while PUBLIC
    await db.cyrusModPage.update({ where: { rootBuildId: ROOT }, data: { visibility: "PUBLIC", hiddenAt: new Date(), hiddenReason: "test" } });
    assert.equal((await S.lifecycleForServer(ids.sb))[0].updateAvailable, false);
    await db.cyrusModPage.update({ where: { rootBuildId: ROOT }, data: { hiddenAt: null, hiddenReason: null } });
  });

  it("NxLabs publish gate: a head whose Test Flight FAILED cannot be published while the block is on (both publish paths share it)", async () => {
    const { publishBlockedReason } = await import("../lib/cyrus-mods/publish-gate.ts");
    assert.equal(await publishBlockedReason(ids.a, ROOT, {}), null);
    await db.modBuild.update({ where: { id: `${uniq}v5` }, data: { cyrus: { testFlight: { state: "done", verdict: "failed", version: "1.21.11", checks: [{ id: "plugin_enabled", status: "fail" }] } } as never } });
    const why = await publishBlockedReason(ids.a, ROOT, { CYRUS_TESTFLIGHT_BLOCK_ON_FAIL: "1" });
    assert.ok(why && why.length > 10, String(why));
  });

  it("installs never touch Cyrus tokens (no hold, no ledger row): only builds are metered", async () => {
    const before = await db.cyrusTokenLedger.count({ where: { userId: ids.a } }).catch(() => 0);
    const holds = await db.cyrusTokenReservation.count({ where: { userId: ids.a } }).catch(() => 0);
    assert.ok((await Q.enqueueModOp(ids.sa, ids.mod, "update", { userId: ids.a, slug: "x" }, { targetVersionId: ROOT })).ok);
    await runJobs(ids.sa);
    assert.equal(await db.cyrusTokenLedger.count({ where: { userId: ids.a } }).catch(() => 0), before);
    assert.equal(await db.cyrusTokenReservation.count({ where: { userId: ids.a } }).catch(() => 0), holds);
  });

  it("server deleted: install rows cascade; Cyrus' FK-less records (managed refs, open signals, last-install pointer) are cleaned", async () => {
    const { cyrusOnServerDeleted } = await import("../lib/cyrus/worker/schedule.ts");
    const sid = ids.sa2;
    await db.cyrusServerManagedPlugin.create({ data: { serverId: sid, key: "bettermodel", family: "1.21", status: "installed", dependents: [`mod:${ROOT}`], refCount: 1 } });
    await db.cyrusModSignal.create({ data: { serverId: sid, modId: ids.mod, rootBuildId: ROOT, kind: "BROKEN", evidence: "x" } });
    await db.modBuild.update({ where: { id: ROOT }, data: { lastInstall: { serverId: sid, serverName: "sa2", at: new Date().toISOString() } } });
    await db.serverMod.create({ data: { serverId: sid, modId: ids.mod, status: "INSTALLED", versionId: ROOT } });
    await db.job.updateMany({ where: { serverId: sid }, data: { serverId: null } });
    await db.server.delete({ where: { id: sid } });
    ids.sa2 = "";
    assert.equal(await db.serverMod.count({ where: { serverId: sid } }), 0, "ServerMod cascades");
    assert.equal(await db.cyrusServerManagedPlugin.count({ where: { serverId: sid } }), 1, "before the hook: orphaned");
    await cyrusOnServerDeleted(sid);
    assert.equal(await db.cyrusServerManagedPlugin.count({ where: { serverId: sid } }), 0);
    assert.equal(await db.cyrusModSignal.count({ where: { serverId: sid, clearedAt: null } }), 0);
    assert.equal((await build(ROOT)).lastInstall, null);
    await cyrusOnServerDeleted(sid); // idempotent
    // the GameMod (one per mod, not per server) stays for the other servers
    assert.equal(await db.gameMod.count({ where: { source: "cyrus", sourceId: ROOT } }), 1);
  });
});

