import { describe, it, before, after } from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { mkdtempSync, writeFileSync, existsSync, readdirSync, mkdirSync, rmSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { writeZip } from "../lib/mod-autoupdate/zip.ts";

/**
 * Cyrus <-> Nxeon integration, END TO END against a THROWAWAY Postgres and the SANDBOX guest filesystem (a temp folder
 * stands in for each server's disk; lib/mods/guest-fs.ts LocalGuestFs). Real install entry points
 * (lib/modbuilder/install.ts installBuildToServer, lib/mods/queue.ts enqueueModOp, lib/modbuilder/delivery.ts
 * enqueueCyrusDelivery), the REAL worker job handler (worker/game-mods.ts gameModSync, which also hands delivery jobs to
 * worker/cyrus-delivery.ts), real read models (lifecycle, Mods tab info, install plans), real NxLabs page sync. No SSH,
 * no network, no mocks of the code under test; the one stand-in is the delivery health check's fake server
 * (test/_cyrus-delivery-fakehost.ts) for the rollback case, because a sandbox has nothing to boot.
 *
 * Opt-in, fail-closed: CYRUS_INTEGRATION_DB_TEST=1 and DATABASE_URL = 127.0.0.1:5433/wt_*. Schema: `devhost db push`.
 *   devhost run --lock -- env CYRUS_INTEGRATION_DB_TEST=1 npx tsx --test test/cyrus-nxeon-integration-db.test.ts
 */
const url = process.env.DATABASE_URL ?? "";
const safe = process.env.CYRUS_INTEGRATION_DB_TEST === "1" && /^postgres(ql)?:\/\/[^@]*@127\.0\.0\.1:5433\/wt_[a-z0-9_]+(\?.*)?$/.test(url);
const skip = safe ? false : "set CYRUS_INTEGRATION_DB_TEST=1 with a node-2 throwaway DATABASE_URL to run";

if (safe) {
  const shimDir = path.join(import.meta.dirname, "..", "node_modules", "server-only");
  const OUR_SHIM = "module.exports = {};\n";
  if (!existsSync(path.join(shimDir, "index.js")) || readFileSync(path.join(shimDir, "index.js"), "utf8") !== OUR_SHIM) {
    mkdirSync(shimDir, { recursive: true });
    writeFileSync(path.join(shimDir, "package.json"), '{"name":"server-only","version":"0.0.0","main":"index.js","browser":"index.js"}\n');
    writeFileSync(path.join(shimDir, "index.js"), OUR_SHIM);
  }
}

const guestDir = mkdtempSync(path.join(tmpdir(), "cyrus-integ-guest-"));
const jarDir = mkdtempSync(path.join(tmpdir(), "cyrus-integ-jars-"));
process.env.NXEON_SANDBOX = "1";
process.env.NXEON_SANDBOX_GUEST_DIR = guestDir;
process.env.CYRUS_DELIVERY = "1";

type Db = typeof import("../lib/db.ts")["db"];
let db: Db;
let W: typeof import("../worker/game-mods.ts");
let I: typeof import("../lib/modbuilder/install.ts");
let Q: typeof import("../lib/mods/queue.ts");
let S: typeof import("../lib/cyrus/lifecycle/server.ts");
let INF: typeof import("../lib/cyrus-mods/installed.ts");
let DL: typeof import("../lib/modbuilder/delivery.ts");

const uniq = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
const ROOT = `${uniq}r1`;
const ids = { a: "", b: "", sa: "", sa2: "", sb: "", sx: "", mod: "", plan: "", os: "", gp: "" };
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const CAPS = { version: 1, network: { hosts: [{ host: "api.example.com", purpose: "prices" }], playerData: [], maxResponseKiB: 64 }, secrets: [], ai: false };

function jarBytes(version: string, main = "com.nxeon.CoinShop", name = "CoinShop") {
  return writeZip([
    { name: "plugin.yml", data: Buffer.from(`name: ${name}\nversion: '${version}'\nmain: ${main}\napi-version: '1.21'\ncommands:\n  coinshop:\n    description: open the shop\n`) },
    { name: `${main.replace(/\./g, "/")}.class`, data: Buffer.from(`class-${version}-${main}`) },
  ]);
}
let n = 0;
async function mkBuild(id: string, version: string, o: { root?: string; userId?: string; status?: string; result?: Record<string, unknown>; main?: string; name?: string } = {}) {
  const bytes = jarBytes(version, o.main, o.name);
  const jarPath = path.join(jarDir, `${id}.jar`);
  writeFileSync(jarPath, bytes);
  const root = o.root ?? ROOT;
  n++;
  return db.modBuild.create({
    data: {
      id, userId: o.userId ?? ids.a, prompt: "A coin shop with /coinshop", status: o.status ?? "succeeded", mcVersion: "1.21.11", pluginName: o.name ?? "CoinShop", version,
      rootBuildId: id === root ? null : root, baseBuildId: id === root ? null : root, jarName: `${o.name ?? "CoinShop"}-${version}.jar`, jarPath, jarSize: bytes.length, jarSha256: sha(bytes),
      result: { summary: { tagline: "Coins", text: "Coins", changes: `v${version}` }, safety: { verdict: "pass" }, ...(o.result ?? {}) },
      createdAt: new Date(Date.now() - 3600_000 + n * 1000), finishedAt: new Date(),
    } as never,
  });
}
async function mkServer(userId: string, name: string, o: { variant?: string; status?: string } = {}) {
  const s = await db.server.create({ data: { name: `${name}-${uniq}`, hostname: `${name}-${uniq}.test`, userId, planId: ids.plan, osTemplateId: ids.os, gamePlanId: ids.gp, status: o.status ?? "RUNNING", gameVariant: o.variant ?? "paper", gameConfig: { VERSION: "1.21.11" } } as never });
  return s.id;
}
/** Stand-in for the worker loop: run every queued GAME_MOD_SYNC for a server, DONE or FAILED like worker/index.ts. */
async function runJobs(serverId: string) {
  const jobs = await db.job.findMany({ where: { serverId, status: "QUEUED", type: "GAME_MOD_SYNC" }, orderBy: { createdAt: "asc" } });
  const errors: string[] = [];
  for (const j of jobs) {
    await db.job.update({ where: { id: j.id }, data: { status: "RUNNING" } });
    try { await W.gameModSync(j); await db.job.update({ where: { id: j.id }, data: { status: "DONE" } }); }
    catch (e) { errors.push((e as Error).message); await db.job.update({ where: { id: j.id }, data: { status: "FAILED", error: (e as Error).message.slice(0, 500) } }); }
  }
  return { count: jobs.length, errors };
}
const row = (serverId: string, modId = ids.mod) => db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId } } });
const plugins = (serverId: string) => { const d = path.join(guestDir, serverId, "opt/mc/plugins"); return existsSync(d) ? readdirSync(d).filter((f) => f.endsWith(".jar")).sort() : []; };
const build = (id: string) => db.modBuild.findUniqueOrThrow({ where: { id } });
const setSetting = (key: string, value: string) => db.setting.upsert({ where: { key }, create: { key, value }, update: { value } });

