test("delivery preflight: the version the Mods engine installed for THIS mod is not 'another jar with the same name' (host.jar.ownedFiles)", async () => {
  const { deliverMod } = await import("../lib/cyrus/delivery/orchestrator.ts");
  const { FakeServer, seedServer, h, BASE } = await import("./_cyrus-delivery-fakehost.ts");
  const s = new FakeServer(); seedServer(s);
  try {
    const engineJar = `${BASE}/plugins/CoinShop-1.0.0.jar`;
    writeFileSync(path.join(s.dir, "opt/mc/plugins/CoinShop-1.0.0.jar"), jar("CoinShop", "1.0.0")); // placed by the Mods tab install (no delivery record)
    const next = jar("CoinShop", "1.1.0");
    const release = { projectId: "cp_int1", revisionId: "r2", namespace: "nx_integ001", mcVersion: "1.21.11", label: "CoinShop", plugin: { pluginName: "CoinShop", jarName: "CoinShop-1.1.0.jar", sha256: h(next), bytes: next }, pack: null, datapacks: [], creatures: [] };
    // Without the host telling it which files are its own, the preflight blocks the mod's own update:
    const before = await deliverMod("s1", release, s.host(), { restartPolicy: "next_restart" });
    assert.equal(before.outcome, "refused");
    assert.match(before.error ?? "", /Two jars declare the plugin name 'CoinShop'/);
    // With ownedFiles (Nxeon: the engine state's package cyrus:<root>) it is an update of the same mod:
    const base = s.host();
    const after = await deliverMod("s1", release, { ...base, jar: { ...base.jar, ownedFiles: async () => [engineJar] } }, { restartPolicy: "next_restart" });
    assert.ok(after.ok, JSON.stringify(after));
    assert.equal(after.outcome, "pending_restart");
    // a REAL second copy (not owned) still blocks
    writeFileSync(path.join(s.dir, "opt/mc/plugins/coinshop-copy.jar"), jar("CoinShop", "0.5.0"));
    const again = await deliverMod("s1", { ...release, revisionId: "r3" }, { ...base, jar: { ...base.jar, ownedFiles: async () => [engineJar] } }, { restartPolicy: "next_restart" });
    assert.equal(again.outcome, "refused");
  } finally { s.cleanup(); }
});
EOF

