// REAL delivery runs on node-2 (not part of the unit suite). The DELIVERY ORCHESTRATOR drives a disposable server dir
// under /tank/nxeon-build/tmp/cyrus-r12/ through a host whose "restart" boots the dir's CURRENT contents on a real Paper
// server with Test Flight (every plugin jar, every world data pack, the Pack Loader config), and whose health probe
// reads that flight's report. So every restart and every health verdict below is a real Paper boot.
//   scripts/devhost run -- npx tsx test/cyrus-delivery-real.ts --local [--version 1.21.11] [--out file.json]
// Scenarios (one flight at a time, busy retried with backoff):
//   A  fresh delivery: mod jar (TfItemModel fixture) + resource pack entry (Pack Loader, packs.json) + a real data pack
//      (the data pack studio showcase) -> restart -> healthy.
//   B  update that adds a deliberately BROKEN world generation pack -> the server does not come up -> rollback restores
//      the exact previous bytes -> restart -> the server comes up healthy on the previous state.
//   C  update with a VALID world generation pack (the worldgen showcase) -> restart -> came up, dimension pack loaded.
//   D  uninstall -> restart -> healthy, jar + packs gone, Pack Loader released.
import { spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import path from "node:path";
import { runTestFlight, type Remote, type RunResult } from "../lib/cyrus/testflight/client";
import type { TestFlightSpec } from "../lib/cyrus/testflight/types";
import { LocalGuestFs } from "../lib/mods/guest-fs";
import { inspectJar } from "../lib/cyrus/inventory/jar";
import { buildDataPack } from "../lib/cyrus/datapack/emit";
import { zip } from "../lib/cyrus/textures/zip";
