function walk(dir: string, out: string[] = []): string[] {
  for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); }
  return out;
}

function build(r: ModCompileOk, lane: (typeof LANES)[number], tag: string, withApi: boolean) {
  const dir = path.join(RUN, `${lane.version}-${tag}`);
  rmSync(dir, { recursive: true, force: true });
  for (const f of r.files) { const abs = path.join(dir, "ws", f.path); mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, f.content); }
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const sources = walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).sort();
  const cp = [readFileSync(lane.cp, "utf8").replace(/\n/g, "").trim(), ...(withApi ? lane.api : [])].join(":");
  const t0 = Date.now();
  let javacOut = "";
  try { javacOut = execFileSync(`${lane.jdk}/bin/javac`, ["-J-Xmx768m", "--release", lane.release, "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
  catch (e) { const x = e as { stdout?: string; stderr?: string }; throw new Error(`javac failed on ${lane.version} ${tag}:\n${(x.stderr ?? "") + (x.stdout ?? "")}`.slice(0, 16000)); }
  const javacMs = Date.now() - t0;
  for (const f of ["plugin.yml", "config.yml"]) writeFileSync(path.join(classes, f), readFileSync(path.join(dir, "ws/src/main/resources", f)));
  const entries = walk(classes).map((f) => path.relative(classes, f)).sort();
  const jarPath = path.join(dir, `${PLUGIN}-${lane.version}-${tag}.jar`);
  execFileSync(`${lane.jdk}/bin/jar`, ["--create", "--file", jarPath, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]);
  // strict safety scan (bytecode + source), like the build service
  const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
  const oldPath = process.env.PATH;
  process.env.PATH = `${lane.jdk}/bin:${oldPath}`;
  let scan;
  try {
    const all = [...S.scanBytecode(classes, { profile: "strict" }), ...S.scanSource(walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).map((abs) => ({ abs, rel: path.relative(path.join(dir, "ws"), abs) })), { profile: "strict" })];
    scan = { blocks: all.filter((f: { severity: string }) => f.severity === "block").length, warnings: all.filter((f: { severity: string }) => f.severity === "warn").length, findings: all.map((f: { severity: string; rule: string; where: string }) => `${f.severity}:${f.rule}@${f.where}`) };
  } finally { process.env.PATH = oldPath; }
  return { dir, sources: sources.length, classFiles: entries.filter((e) => e.endsWith(".class")).length, javacMs, javacWarnings: (javacOut.match(/warning:/g) ?? []).length, javacOut: javacOut.slice(0, 3000), jarPath, jarSha256: sha(readFileSync(jarPath)), scan };
}

function harvest(runId: string | null) {
  const out: Record<string, unknown> = {};
  if (!runId || !/^[A-Za-z0-9_-]+$/.test(runId)) return out;
  const dir = path.join(TF, "runs", runId);
  const log = path.join(dir, "logs/latest.log");
  const lines = existsSync(log) ? readFileSync(log, "utf8").split("\n") : [];
  out.logLines = lines.length;
  out.pluginLog = lines.filter((l) => new RegExp(`${PLUGIN}|BetterModel`, "i").test(l)).map((l) => l.slice(0, 300)).slice(0, 80);
  // the sandbox has no internet: authlib's public-key fetch (and its stack) is Test Flight noise, not the mod
  const noise = (l: string) => /minecraftservices\.com|com\.mojang\.authlib|yggdrasil|fill\.papermc\.io|PaperVersionFetcher/i.test(l);
  const exc = lines.filter((l) => /Exception|Caused by|^\s+at /.test(l));
  out.exceptionLines = exc.filter((l) => !noise(l) && !/^\s+at (com\.mojang\.authlib|java\.|jdk\.|net\.minecraft\.server\.Services)/.test(l)).map((l) => l.slice(0, 300)).slice(0, 30);
  out.sandboxNoiseExceptionLines = exc.length - (out.exceptionLines as string[]).length;
  out.pluginErrorLines = lines.filter((l) => /\/(ERROR|FATAL)\]/.test(l) && new RegExp(PLUGIN, "i").test(l)).map((l) => l.slice(0, 300)).slice(0, 20);
  out.errorLines = lines.filter((l) => /\/(ERROR|FATAL)\]/.test(l)).map((l) => l.slice(0, 300)).slice(0, 20);
  out.modelWarnings = lines.filter((l) => /model .* not worn/.test(l)).map((l) => l.slice(0, 300));
  out.cleanupLines = lines.filter((l) => /cleanup: /.test(l)).map((l) => l.slice(0, 300));
  out.cantKeepUp = lines.filter((l) => /Can't keep up/.test(l)).length;
  rmSync(dir, { recursive: true, force: true });
  return out;
}

