import { readFileSync } from "node:fs";
import path from "node:path";
import { compileMod, type ModCompileOk } from "../../lib/cyrus/designer/gameplay/compile";
import { checkRigSpec } from "../../lib/cyrus/creature/spec";
import { compileCreature } from "../../lib/cyrus/creature/compile";

const FX = path.join(__dirname, "../../test/fixtures/cyrus-boss-model");
export const BM_NS = "nx_b0ssm0de";
export const BM_PLUGIN = "HollowKing";
export const BM_DESIGNS = ["hollow_king", "hollow_siege"];
export const BM_RIGS = ["hollow_king", "hollow_thrall"];
export const BM_VERSIONS = ["1.21.11", "26.2"];
export const loadBmDesigns = () => BM_DESIGNS.map((n) => JSON.parse(readFileSync(path.join(FX, `${n}.json`), "utf8")));
export const loadBmRig = (n: string) => JSON.parse(readFileSync(path.join(FX, `${n}.rig.json`), "utf8"));

/** rig name -> its declared hitbox height (what the build service passes the designer compile). */
export const bmRigHeights = (): Record<string, number> => Object.fromEntries(BM_RIGS.map((n) => [n, loadBmRig(n).hitbox.height]));
export function compileBm(version = "1.21.11", rigs: string[] | undefined = BM_RIGS): ModCompileOk {
  const r = compileMod(loadBmDesigns(), { version, namespace: BM_NS, pluginName: BM_PLUGIN, ...(rigs ? { assets: { rigs, rigHeights: bmRigHeights() } } : {}) });
  if (!r.ok) throw new Error(JSON.stringify(r.errors, null, 1));
  return r;
}

/** The .bbmodel files of the two rigs (Nxeon's creature compiler, as the portal delivers them). */
export function bmModels(): { key: string; bbmodel: string; bytes: number }[] {
  return BM_RIGS.map((n) => {
    const c = checkRigSpec(loadBmRig(n), { namespace: BM_NS });
    if (!c.ok) throw new Error(`${n}: ${c.error}`);
    const m = compileCreature(c.spec, BM_NS, {});
    if (!m.ok) throw new Error(`${n}: ${m.error}`);
    return { key: m.creature.key, bbmodel: m.creature.bbmodel, bytes: Buffer.byteLength(m.creature.bbmodel) };
  });
}

