const VERSION = "1.21.11";
const BM_JAR = `${TF}/bettermodel/BetterModel-2.2.0-paper.jar`;
const GOLDEN = process.argv.includes("--golden") ? process.argv[process.argv.indexOf("--golden") + 1] : `${TF}/mc-coverage/${VERSION}/mc-economy.jar`;
