  for (const f of c.files) { const abs = path.join(dir, "ws", f.path); mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, f.content); }
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const sources = walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).sort();
  const cp = [readFileSync(`${TF}/classpath/${VERSION}.txt`, "utf8").replace(/\n/g, "").trim(), `${T}/mc-coverage/deps/bettermodel-api-2.2.0.jar`, `${T}/mc-coverage/deps/bettermodel-bukkit-api-2.2.0.jar`].join(":");
  execFileSync(`${TF}/jdk/21/bin/javac`, ["-J-Xmx768m", "--release", "21", "-proc:none", "-encoding", "UTF-8", "-cp", cp, "-d", classes, ...sources], { stdio: ["ignore", "pipe", "pipe"] });
  for (const f of ["plugin.yml", "config.yml"]) writeFileSync(path.join(classes, f), readFileSync(path.join(dir, "ws/src/main/resources", f)));
