  const out: CyrusJar = { build: { id: j.id, version: j.version, pluginName: j.plugin, jarName: `${j.plugin}-${j.version}.jar`, jarSha256: sha(j.bytes), mcVersion: VERSION }, name: j.name, packageVersion: j.version, bytes: j.bytes };
