  execFileSync(`${TF}/jdk/21/bin/jar`, ["--create", "--file", jarPath, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]);
  return readFileSync(jarPath);
}

