const cyrusMod = (root: string, name: string): CatalogFacts => ({ id: `gm-${root}`, gameFamily: "minecraft", slug: `cyrus-${root}`, name, source: CYRUS_SOURCE, sourceId: root, url: null, category: "Plugins", appliesToVariant: null, loaders: ["paper", "purpur"], gameVersions: [VERSION], serverSide: "required" });

async function main() {
  const res: Record<string, unknown> = { at: new Date().toISOString(), host: "node-2", paper: VERSION, realClient: false, steps: [] as unknown[] };
  const steps = res.steps as Record<string, unknown>[];
  const save = () => { const o = arg("--out"); if (o) { mkdirSync(path.dirname(o), { recursive: true }); writeFileSync(o, JSON.stringify(res, null, 1)); } };
  mkdirSync(WORK, { recursive: true });
  const srv = path.join(WORK, "server");
  const fs = new LocalGuestFs(srv);
  await seedSandboxGuest(fs, "minecraft", "paper");
  const PL = path.join(srv, "opt/mc/plugins");
  const server: ServerFacts = { id: "integ-real", family: "minecraft", variant: "paper", pinnedVersion: VERSION, config: null };
  const deps = { fs, fetcher: async (): Promise<never> => { throw new Error("no downloads in this run"); } };
  const pluginsOnDisk = () => readdirSync(PL).filter((f) => f.endsWith(".jar")).sort();

  // the managed BetterModel: the catalogue pin for 1.21.11, checked against the real artifact
  const catalog = loadCatalog();
  const pin = pinFor(catalog, "bettermodel", VERSION);
  if (!pin.ok) throw new Error(`no BetterModel pin for ${VERSION}: ${JSON.stringify(pin)}`);
  const bmBytes = readFileSync(BM_JAR);
  if (sha(bmBytes) !== pin.entry.sha256) throw new Error(`BetterModel jar sha256 ${sha(bmBytes)} is not the pinned ${pin.entry.sha256}`);
  const managedInstaller: FamilyInstaller = { ...minecraftInstaller, sources: ["nxeon-managed"], resolve: async () => managedResolution(pin.entry, bmBytes), legacyPaths: () => [] };
  const bmFacts = managedFacts(pin.entry);

  /** Boot the directory as it is now. */
  const boot = async (label: string, rcon: RconCheck[], extraFiles: { path: string; content: string }[] = []) => {
    const plugins = pluginsOnDisk().map((f) => { const b = readFileSync(path.join(PL, f)); return { localPath: path.join(PL, f), sha256: sha(b) }; });
    const files = [...extraFiles];
    for (const f of walk(PL).filter((p) => /\/plugins\/[^/]+\/[^/]+\.(yml|bbmodel)$|\/plugins\/BetterModel\/models\/[^/]+\.bbmodel$/.test(p))) {
      const rel = path.relative(path.join(srv, "opt/mc"), f);
      if (!files.some((x) => x.path === rel)) files.push({ path: rel, content: readFileSync(f, "utf8") });
    }
    const hasBm = pluginsOnDisk().some((f) => /^BetterModel/i.test(f));
    const t0 = Date.now();
    const r = await fly({
      version: VERSION, plugins, ...(files.length ? { files: files.slice(0, 16) } : {}), rcon, keepDir: true,
      ...(hasBm ? { seeds: [{ from: "bettermodel-2.2.0-paper-libraries", to: "libraries" }, { from: "bettermodel-2.2.0-libby", to: "plugins/BetterModel/.libs" }] } : {}),
      timeouts: { bootSec: 300, rconSec: 30, stopSec: 90, totalSec: 600 }, memory: { xmxMb: 1024, rssCapMb: 2048 },
    }, label);
    const runDir = r.report.runId && /^[A-Za-z0-9_-]+$/.test(r.report.runId) ? path.join(TF, "runs", r.report.runId) : null;
    const log = runDir && existsSync(path.join(runDir, "logs/latest.log")) ? readFileSync(path.join(runDir, "logs/latest.log"), "utf8").split("\n") : [];
    if (runDir) rmSync(runDir, { recursive: true, force: true });
    const out = {
      label, wallMs: Date.now() - t0, overall: r.summary.overall, line: describeSummary(r.summary), bootMs: r.report.bootMs, paper: r.report.engine?.paper ?? null,
      flown: plugins.map((p) => path.basename(p.localPath)), files: files.map((f) => f.path),
      checks: r.report.checks.map((x) => ({ id: x.id, status: x.status, evidence: x.evidence.slice(0, 30) })),
      enabling: log.filter((l) => /Enabling |Disabling |Ambiguous plugin name|Could not load/.test(l)).map((l) => l.slice(0, 220)).slice(0, 40),
    };
    console.log(`${label}: ${out.line}`);
    for (const c of out.checks) if (c.status !== "pass" || c.id === "rcon_checks") console.log(`  ${c.id}: ${c.status}\n    ${c.evidence.slice(0, 20).join("\n    ")}`);
    return out;
  };

  try {
    // ── 1. golden plugin v1 ──────────────────────────────────────────────────
    const g1 = readFileSync(GOLDEN);
    const gid = pluginIdentity(g1);
    if (!gid) throw new Error(`${GOLDEN} has no plugin.yml`);
    const golden = cyrusMod("goldenroot1", gid.name);
    jars.set("goldenroot1", { id: "golden-v1", bytes: g1, name: gid.name, plugin: gid.name, version: gid.version ?? "1.0.0" });
    let r = await installOrUpdate(minecraftInstaller, golden, server, deps);
    if (!r.ok) throw new Error(`install golden: ${r.error}`);
    mkdirSync(path.join(PL, gid.name), { recursive: true });
    const ownerConfig = `# edited by the owner before the update\nnxeon-integ-marker: kept-${Date.now()}\n`;
    const b1 = await boot("1 golden v1", [{ id: "plugins", command: "plugins", expect: [gid.name] }]);
    steps.push({ step: "1 install golden v1", engine: { changed: r.changed, notes: r.notes, version: r.version }, disk: pluginsOnDisk(), boot: b1 });
    save();

    // ── 2. update to v2 over v1, owner config in place ───────────────────────
    writeFileSync(path.join(PL, gid.name, "nxeon-integ-owner.yml"), ownerConfig);
    const v2 = `${gid.version ?? "1.0.0"}-integ2`;
    jars.set("goldenroot1", { id: "golden-v2", bytes: bumpVersion(g1, v2), name: gid.name, plugin: gid.name, version: v2 });
    r = await installOrUpdate(minecraftInstaller, { ...golden, targetVersionId: "golden-v2" }, server, deps, "update");
    if (!r.ok) throw new Error(`update golden: ${r.error}`);
    const keptConfig = readFileSync(path.join(PL, gid.name, "nxeon-integ-owner.yml"), "utf8") === ownerConfig;
    const backups = path.join(srv, "root/.nxeon-mods/backups");
    const configBackedUp = readdirSync(backups).some((d) => existsSync(path.join(backups, d, `opt/mc/plugins/${gid.name}/nxeon-integ-owner.yml`)));
    const b2 = await boot("2 golden v2", [{ id: "plugins", command: "plugins", expect: [gid.name] }]);
    steps.push({ step: "2 update golden v1 -> v2", engine: { changed: r.changed, version: r.version }, disk: pluginsOnDisk(), ownerConfigKept: keptConfig, configBackedUp, v2EnabledInLog: (b2.enabling as string[]).some((l) => l.includes(`Enabling ${gid.name} v${v2}`)), boot: b2 });
    save();

    // ── 3. creature mod: managed BetterModel + The Hollow King + models + managed config ─
    const hk = buildHollowKing();
    jars.set("hollowroot1", { id: "hollow-v1", bytes: hk, name: "The Hollow King", plugin: BM_PLUGIN, version: "1.0.0" });
    const bm = await installOrUpdate(managedInstaller, bmFacts, server, deps);
    if (!bm.ok) throw new Error(`managed BetterModel: ${bm.error}`);
    const hkr = await installOrUpdate(minecraftInstaller, cyrusMod("hollowroot1", "The Hollow King"), server, deps);
    if (!hkr.ok) throw new Error(`install Hollow King: ${hkr.error}`);
    mkdirSync(path.join(PL, "BetterModel/models"), { recursive: true });
    writeFileSync(path.join(PL, "BetterModel/config.yml"), managedConfigTemplate(VERSION));
    for (const m of bmModels()) writeFileSync(path.join(PL, `BetterModel/models/${m.key}.bbmodel`), m.bbmodel);
    const CMD = BM_PLUGIN.toLowerCase();
    const KEY = `${BM_NS}_hollow_king`;
    const b3 = await boot("3 creature mod", [
      { id: "plugins", command: "plugins", expect: ["BetterModel", BM_PLUGIN, gid.name] },
      { id: "forceload", command: "forceload add ~-32 ~-32 ~32 ~32", expect: ["chunks"] },
      { id: "models-wait", command: `${CMD} boss list`, waitMs: 10000, expect: [`model=${KEY}`] },
      { id: "spawn", command: `${CMD} boss spawn hollow_king spawn`, expect: ["Spawned hollow_king#1", `model ${KEY} attached`] },
      { id: "status", command: `${CMD} boss status`, expect: [`model ${KEY} attached`] },
    ]);
    steps.push({ step: "3 creature mod (managed BetterModel + Hollow King)", engine: { bettermodel: { changed: bm.changed, version: bm.version }, hollowKing: { changed: hkr.changed } }, disk: pluginsOnDisk(), boot: b3 });
    save();

    // ── 4. already-on-the-server recognition (no boot needed: nothing may change) ─
    writeFileSync(path.join(PL, "BetterModel-handcopy.jar"), bmBytes);
    const again = await installOrUpdate(managedInstaller, bmFacts, server, deps);
    const dupRefused = await (async () => {
      // a NEW version of the managed plugin with a hand copy present must refuse (the idempotent re-run above changes nothing)
      const bm2: FamilyInstaller = { ...managedInstaller, resolve: async () => { const res2 = managedResolution({ ...pin.entry, version: "2.2.0-integ" }, bumpVersion(bmBytes, "2.2.0-integ")); res2.packages[0].file.hashes = {}; return res2; } };
      return installOrUpdate(bm2, bmFacts, server, deps, "update");
    })();
    rmSync(path.join(PL, "BetterModel-handcopy.jar"));
    steps.push({ step: "4 recognition", idempotentReinstall: again.ok ? { changed: again.changed, notes: again.notes } : again, updateWithHandCopy: dupRefused.ok ? { ok: true, changed: dupRefused.changed } : { ok: false, error: dupRefused.error }, disk: pluginsOnDisk() });
    save();

    // ── 5. uninstall everything Nxeon placed ─────────────────────────────────
    const u1 = await uninstall(minecraftInstaller, golden, server, deps);
    const u2 = await uninstall(minecraftInstaller, cyrusMod("hollowroot1", "The Hollow King"), server, deps);
    const u3 = await uninstall(managedInstaller, bmFacts, server, deps);
    const st = await loadState(fs, "minecraft");
    const b5 = await boot("5 after uninstall", [{ id: "plugins", command: "plugins", expectNot: [gid.name, BM_PLUGIN, "BetterModel"] }]);
    steps.push({ step: "5 uninstall all", engine: [u1, u2, u3].map((u) => (u.ok ? { changed: u.changed } : u)), disk: pluginsOnDisk(), stateRoots: Object.keys(st.roots), statePackages: Object.keys(st.packages), dataFoldersKept: readdirSync(PL).filter((f) => !f.endsWith(".jar")), boot: b5 });
    save();
  } finally {
    setCyrusJarSource(null);
    save();
    rmSync(WORK, { recursive: true, force: true });
  }
  console.log(JSON.stringify(steps.map((s) => ({ step: s.step, disk: s.disk, boot: (s.boot as { overall?: string } | undefined)?.overall })), null, 1));
}

main().catch((e) => { console.error(e); setCyrusJarSource(null); process.exit(1); });

